const MessageMatchCut: React.FC<MessageMatchCutProps> = ({
  messageText = "hello world",
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 6,
  framesPerStyle = 30,
  scale = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Array of component styles to loop through
  const styles = [
    InstaComment,
    BlueLink,
    YellowHighlight,
    CodeBlock,
    BlueSelection,
    SafariBar,
    TextCursor,
    GreenSelection,
    SMSWhite,
    WhatsAppLight,
    IOSGreen,
    GenericGrey,
    IMessageBlue,
    AppleNotes,
  ];

  // Determine which style is currently active
  const currentIndex = Math.floor(frame / framesPerStyle) % styles.length;
  const CurrentStyleComponent = styles[currentIndex];

  // Local frame for the pop animation on every cut
  const localFrame = frame % framesPerStyle;

  // Spring animation for a slight scale "pop" when cutting to a new style
  const popScale = spring({
    fps,
    frame: localFrame,
    config: {
      damping: 14,
      mass: 0.6,
      stiffness: 250,
    },
  });

  // Map the spring value to a subtle scale range (starts slightly smaller, bounces to 1)
  const animatedScale = interpolate(popScale, [0, 1], [0.94, 1]);
  const finalScale = animatedScale * scale;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        WebkitFontSmoothing: "antialiased",
      }}
    >
      <div
        style={{
          transform: `scale(${finalScale})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
        }}
      >
        <CurrentStyleComponent text={messageText} width={width} />
      </div>
    </AbsoluteFill>
  );
};

export default MessageMatchCut;